using System;
using System.Collections;
using System.Collections.Generic;
using Astrea.RunModifiers;
using FMODUnity;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ReshuffleDiscardedDicesHandler", menuName = "Data/Battle/Handlers/Reshuffle Discarded Dices Handler")]
public class ReshuffleDiscardedDicesHandler : ScriptableObject
{
	[Header("Pools")]
	[SerializeField]
	private TransformReference discardPoolButtonTransformReference;

	[Header("Receive Dice Animation")]
	[SerializeField]
	private GameObject receiveDiceAnimationPrefab;

	[Header("SFX")]
	[SerializeField]
	private EventReference uiDeckShuffleOut;

	public IEnumerator ReshuffleDices(bool duringBattle = true)
	{
		if (duringBattle)
		{
			ReferenceSingleton<MiscOmensHandler>.Instance.ActivateOnOnShuffleDicePoolOmenActions();
			ReferenceSingleton<AssetsReference>.Instance.DifficultyLevels.GetCurrentDifficultyLevelOnShuffleDicePoolAction().InteractThroughItems(delegate(OmenLogicActionFace item)
			{
				item.OmenLogic.ActivateOmen(item.ActionFace.BattleAction, item.ActionFace.ActionValue, null, null);
			});
			ReferenceSingleton<RunModifiersManager>.Instance.OnShuffleDicePoolRunModifierActions.InteractThroughItems(delegate(Action item)
			{
				item();
			});
			List<GameObject> currentActiveUnits = ReferenceSingleton<AssetsReference>.Instance.CurrentActiveUnits.GetCurrentActiveUnits();
			for (int j = 0; j < currentActiveUnits.Count; j++)
			{
				currentActiveUnits[j].GetComponent<UnitEffects>().OnShuffleDicePoolEffects();
			}
		}
		ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.ShuffledPoolAmount++;
		for (int num = ReferenceSingleton<AssetsReference>.Instance.Discard.InventoryItems.Count - 1; num >= 0; num--)
		{
			InventoryItem inventoryItem = ReferenceSingleton<AssetsReference>.Instance.Discard.InventoryItems[num];
			if (!(inventoryItem.dice as PlayerDice).DiceJustPlayed)
			{
				ReferenceSingleton<AssetsReference>.Instance.DrawPool.IncreaseDiceAmount(inventoryItem.dice, inventoryItem.amount, insertAsFirst: false, updateDicePoolText: false);
			}
		}
		List<InventoryItem> discardDiceInvetoryItem = ReferenceSingleton<AssetsReference>.Instance.Discard.GetAllInventoryItemsButJustPlayed().Duplicate();
		ReferenceSingleton<AssetsReference>.Instance.Discard.ClearAllDices(ignoreJustPlayedDice: true);
		for (int i = discardDiceInvetoryItem.Count - 1; i >= 0; i--)
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(uiDeckShuffleOut);
			GameObject @object = ReferenceSingleton<PoolHandler>.Instance.GetObject(receiveDiceAnimationPrefab.name);
			ReceiveDiceAnimation component = @object.GetComponent<ReceiveDiceAnimation>();
			@object.transform.position = discardPoolButtonTransformReference.value.position.ZeroZ() + Vector3.forward * component.DiceRollingZPosition.Value;
			InventoryItem inventoryItem2 = discardDiceInvetoryItem[i];
			component.Initialize(BagEnum.DrawPool, inventoryItem2.dice, ReferenceSingleton<AssetsReference>.Instance.DrawPool, inventoryItem2.amount);
			component.StartAnimation(reshuffling: true);
			yield return new WaitForSeconds(0.1f);
		}
		ReferenceSingleton<AssetsReference>.Instance.DrawPool.UpdateDicePoolText();
		yield return new WaitForSeconds(0.65f);
	}
}
